  .stamp { position: static; display: inline-block; margin: 22px 0 0 4px; font-size: 21px; padding: 9px 14px 6px; transform: rotate(-4deg); }
  header.top { padding-bottom: 26px; } .lineup-wrap { margin-top: 30px; }
  .form dd { max-width: 55%; } .figures { gap: 14px 30px; } .figures dt { font-size: 44px; }
  .field { grid-template-columns: minmax(0, 1fr); gap: 8px; padding: 22px 0; } .margin { grid-column: 1; }
  .verdict { font-size: 21px; } .money { font-size: 34px; } .money small { font-size: 17px; }
  table.docket thead { display: none; } table.docket, table.docket tbody, table.docket tr, table.docket td { display: block; width: auto; }
  table.docket tr { padding: 16px 0; border-bottom: 1px solid var(--rule); } table.docket td { border: 0; padding: 3px 0; } table.docket td.what { width: auto; }
}
