#!/bin/sh
# overflow.sh <width> <html files...>: lay each page out at exactly <width> px in a frame and report anything wider than the frame.
# The lineup's own scroll box is allowed to hold something wider. Nothing else is.
CH="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
w=$1; shift
for page in "$@"; do
  wrap="$(dirname "$0")/.probe.html"
  cat > "$wrap" <<HTML
<!doctype html><meta charset="utf-8"><body><iframe id="f" src="file://$page" style="width:${w}px;height:3000px;border:0"></iframe><pre id="out">waiting</pre>
<script>
document.getElementById('f').addEventListener('load', function () {
  var d = this.contentDocument, wide = [];
  d.querySelectorAll('body *').forEach(function (el) {
    if (el.closest('.scroll') || el.closest('svg')) { return; }
    var r = el.getBoundingClientRect();
    if (r.right > $w + 0.5 && r.width > 0) { wide.push(el.tagName.toLowerCase() + '.' + (el.className && el.className.baseVal === undefined ? el.className : '') + ' right=' + Math.round(r.right)); }
  });
  var spill = [];
  d.querySelectorAll('body *').forEach(function (el) {
    if (el.closest('svg') || el.classList.contains('scroll')) { return; }
    if (el.scrollWidth > el.clientWidth + 1 && el.clientWidth > 0 && !Array.prototype.some.call(el.children, function (c) { return c.scrollWidth > c.clientWidth + 1 && c.clientWidth > 0; })) {
      spill.push(el.tagName.toLowerCase() + '.' + el.className + ' ' + el.scrollWidth + '>' + el.clientWidth + ' "' + el.textContent.trim().slice(0, 40) + '"');
    }
  });
  document.getElementById('out').textContent = 'RESULT scrollWidth=' + d.documentElement.scrollWidth + ' of $w, too wide: ' + (wide.slice(0, 6).join('; ') || 'nothing') + ' | spilling: ' + (spill.slice(0, 5).join('; ') || 'nothing');
});
</script>
HTML
  out=$("$CH" --headless=new --disable-gpu --no-first-run --allow-file-access-from-files --user-data-dir="$(dirname "$0")/chrome-profile" --virtual-time-budget=5000 --dump-dom "file://$wrap" 2>/dev/null &
        pid=$!; n=0; while kill -0 $pid 2>/dev/null && [ $n -lt 30 ]; do n=$((n+1)); perl -e 'select(undef,undef,undef,0.5)'; done; kill $pid 2>/dev/null)
  echo "$(basename "$page") @${w}: $(echo "$out" | grep -o 'RESULT[^<]*' | head -1)"
done

#!/bin/sh
# phone.sh <html file> <png> [height]: a screenshot of the page laid out at exactly 375 px wide, inside a frame.
# Chrome will not make a window narrower than about 500 px, so the page is put in a 375 px iframe.
h=${3:-2400}
wrap="$(dirname "$2")/.phone-$(basename "$2").html"
printf '<!doctype html><meta charset="utf-8"><body style="margin:0;background:#888"><iframe src="file://%s" style="width:375px;height:%spx;border:0;display:block"></iframe>' "$1" "$h" > "$wrap"
"$(dirname "$0")/shot.sh" "$wrap" "$2" 520 "$h"

#!/bin/sh
# where.sh <width> <html file>: the page's height at that width, and where each section starts, in CSS px.
CH="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
wrap="$(dirname "$0")/.where.html"
cat > "$wrap" <<HTML
<!doctype html><meta charset="utf-8"><body><iframe id="f" src="file://$2" style="width:$1px;height:800px;border:0"></iframe><pre id="out">waiting</pre>
<script>
document.getElementById('f').addEventListener('load', function () {
  var d = this.contentDocument, parts = ['height=' + d.documentElement.scrollHeight];
  d.querySelectorAll('section').forEach(function (s) { var h = s.querySelector('h2'); parts.push((h ? h.textContent.trim() : '?') + '=' + Math.round(s.getBoundingClientRect().top + d.defaultView.scrollY) + '+' + Math.round(s.getBoundingClientRect().height)); });
  document.getElementById('out').textContent = 'RESULT ' + parts.join(' | ');
});
</script>
