function Block({ data }) {
  const sets = [data.base, data.down, data.up].filter((d) => d && !d.error && d.rows && d.rows.length && d.series && d.series.length);
  if (!sets.length) return <Text variant="soft">Cash is not available for this view.</Text>;
  const names = sets.map((d, n) => (d.scenario && d.scenario.label) || (n === 0 ? 'Scenario in view' : 'Case ' + (n + 1)));
  const rows = sets[0].rows.map((row, i) => {
    const point = { date: row.date };
    sets.forEach((d, n) => {
      const other = d.rows[i];
      point['case' + n] = other ? other[d.series[0].key] : null;
    });
    return point;
  });
  return (
    <Col>
      <Text variant="heading">Cash at the end of each month, by case</Text>
      <Chart
        height={300}
        options={{
          data: rows,
          series: sets.map((d, n) => ({ type: 'line', xKey: 'date', yKey: 'case' + n, yName: names[n] })),
        }}
      />
      <Text variant="soft">Opening cash is $15,000 and nothing is raised. The table below adds the downside with no founder draw.</Text>
    </Col>
  );
}

const money = (v) => (v < 0 ? '-$' : '$') + Math.abs(Math.round(v)).toLocaleString('en-US');
const percent = (v) => Math.round(v * 100) + '%';
const cents = (v) => '$' + Number(v).toFixed(2);
const keyOf = (set, name) => {
  const found = set.series.find((entry) => entry.label === name || entry.variable === name);
  return found ? found.key : name;
};

function Block({ data, state, emit }) {
  const monthly = data.monthly || { rows: [], series: [] };
  const inputs = data.inputs || { rows: [], series: [] };
  const [levers, setLevers] = React.useState((state && state.levers) || {});
  if (monthly.error || inputs.error || !monthly.rows.length || !inputs.rows.length) {
    return <Text variant="soft">The plan's numbers are not available for this view.</Text>;
  }
  const input = (name) => Number(inputs.rows[0][keyOf(inputs, name)]) || 0;
  const saved = {
    price: input('Team price'),
    usage: input('Usage share'),
    cost: Math.round(input('Cost per investigation') * 100) / 100,
    draw: input('Founder draw per month'),
  };
  const now = { ...saved, ...levers };
  const draft = (name) => (value) => setLevers((old) => ({ ...old, [name]: value }));
  const keep = (name) => (value) => {
    const next = { ...levers, [name]: value };
    setLevers(next);
    emit({ type: 'setState', patch: { levers: next } });
  };
  const reset = () => {
    setLevers({});
    emit({ type: 'setState', patch: { levers: null } });
  };
  const k = {
    team: keyOf(monthly, 'Team agents'),
    scale: keyOf(monthly, 'Scale agents'),
    worker: keyOf(monthly, 'Replay worker cost'),
    fixed: keyOf(monthly, 'Fixed costs'),
    cash: keyOf(monthly, 'Cash'),
    month: keyOf(monthly, 'Plan month'),
  };
  const scalePrice = input('Scale price');
  const teamIncluded = input('Team investigations included');
  const scaleIncluded = input('Scale investigations included');
  const drawFrom = input('Founder draw starts in month');
  let cash = input('Opening cash');
  const rows = monthly.rows.map((row) => {
    const team = Number(row[k.team]) || 0;
    const scale = Number(row[k.scale]) || 0;
    const revenue = team * now.price + scale * scalePrice;
    const investigations = now.usage * (team * teamIncluded + scale * scaleIncluded);
    const draw = (Number(row[k.month]) || 0) >= drawFrom ? now.draw : 0;
    const costs = investigations * now.cost + (Number(row[k.worker]) || 0) + (Number(row[k.fixed]) || 0) + draw;
    cash += revenue - costs;
    return { date: row.date, saved: Number(row[k.cash]), changed: cash, net: revenue - costs };
  });
  const last = rows[rows.length - 1];
  const lowest = rows.reduce((least, row) => (row.changed < least.changed ? row : least), rows[0]);
  const covered = rows.find((row) => row.net >= 0);
  const out = rows.find((row) => row.changed < 0);
  const moved = Object.keys(levers).some((name) => levers[name] !== saved[name]);
  const gap = last.changed - last.saved;
  return (
    <Col>
      <Row align="center">
        <Text variant="heading">What moves the cash</Text>
        {moved ? <Button onClick={reset} data-guide-anchor="simulator-reset">Back to the saved plan</Button> : null}
      </Row>
      <Grid columns={2} minColumnWidth={320}>
        <Col style={{ gap: 16 }}>
          <Slider data-guide-anchor="team-price-slider" label="Team price, a month per agent" value={now.price} min={99} max={499} step={10} formatValue={money} referenceValue={saved.price} referenceLabel="Saved plan" onChange={draft('price')} onCommit={keep('price')} />
          <Slider data-guide-anchor="usage-slider" label="Share of included investigations used" value={now.usage} min={0.1} max={1} step={0.05} formatValue={percent} referenceValue={saved.usage} referenceLabel="Saved plan" onChange={draft('usage')} onCommit={keep('usage')} />
          <Slider data-guide-anchor="cost-slider" label="Cost of one investigation" description="Measured at $1.37 on a small model. A large model costs 5 to 15 times more to replay." value={now.cost} min={0.5} max={20} step={0.01} formatValue={cents} referenceValue={saved.cost} referenceLabel="Saved plan" onChange={draft('cost')} onCommit={keep('cost')} />
          <Slider data-guide-anchor="draw-slider" label="Founder draw, a month" description={'Starts in month ' + drawFrom + '. Set it to $0 for no draw.'} value={now.draw} min={0} max={6000} step={250} formatValue={money} referenceValue={saved.draw} referenceLabel="Saved plan" onChange={draft('draw')} onCommit={keep('draw')} />
        </Col>
        <Col>
          <Grid columns={2} minColumnWidth={150}>
            <Stat data-guide-anchor="cash-at-12" label="Cash after month 12" value={money(last.changed)} delta={moved && Math.round(gap) !== 0 ? money(gap) + ' against the saved plan' : undefined} positive={gap >= 0} />
            <Stat label="Lowest cash" value={money(lowest.changed)} delta={'in ' + lowest.date} positive={lowest.changed >= 0} />
            <Stat label="Costs covered from" value={covered ? covered.date : 'Not this year'} />
            <Stat label="Cash runs out" value={out ? out.date : 'Not this year'} />
          </Grid>
          <Chart
            height={260}
            options={{
              data: rows,
              series: [
                { type: 'line', xKey: 'date', yKey: 'saved', yName: 'Saved plan' },
                { type: 'line', xKey: 'date', yKey: 'changed', yName: 'With these settings' },
              ],
            }}
          />
        </Col>
      </Grid>
    </Col>
  );
}

function Block({ data }) {
  const year = data.year || { rows: [], series: [] };
  if (year.error || !year.rows.length) return <Text variant="soft">The plan's numbers are not available for this view.</Text>;
  const series = (name) => year.series.find((entry) => entry.label === name || entry.variable === name) || { key: name, label: name };
  const revenue = series('Revenue');
  const costs = series('Total costs');
  const cash = series('Cash');
  const margin = series('Gross margin');
  const last = year.rows[year.rows.length - 1];
  const out = year.rows.find((row) => Number(row[cash.key]) < 0);
  return (
    <Col>
      <Text variant="heading">The year, in the scenario in view</Text>
      <Grid columns={2} minColumnWidth={220}>
        <Stat label={'Revenue in ' + last.date} value={formatValue(last[revenue.key], revenue)} />
        <Stat label={'Gross margin in ' + last.date} value={formatValue(last[margin.key], margin)} />
        <Stat label="Cash after month 12" value={formatValue(last[cash.key], cash)} />
        <Stat label="Cash runs out" value={out ? out.date : 'Not this year'} />
      </Grid>
      <Text variant="title">Revenue and total costs by month</Text>
      <Chart
        height={260}
        options={{
          data: year.rows,
          series: [
            { type: 'bar', xKey: 'date', yKey: revenue.key, yName: 'Revenue' },
            { type: 'bar', xKey: 'date', yKey: costs.key, yName: 'Total costs' },
          ],
        }}
      />
    </Col>
  );
}
